=== FILE: rr_arbiter.v ===
// rr_arbiter: round-robin arbiter for N requesters.
// Implements microarchitecture.md (approved) for interface_spec.md (approved).
// - State: one priority pointer ptr, $clog2(N) bits, synchronous active-low
//   reset to 0.
// - Grant: combinational search from ptr upwards, wrapping from LAST (N-1)
//   to 0 by comparison, so any N >= 2 works.
// - Update: on a rising edge with a grant, ptr becomes winner + 1 (wrapping);
//   with no request ptr holds.
`default_nettype none

module rr_arbiter #(
    parameter integer N = 4
) (
    input  wire         clk,
    input  wire         rst_n,
    input  wire [N-1:0] req,
    output reg  [N-1:0] grant
);
    localparam integer  PW     = (N > 1) ? $clog2(N) : 1;
    localparam [31:0]   LAST_W = N - 1;
    localparam [31:0]   ONE_W  = 32'd1;
    localparam [PW-1:0] LAST   = LAST_W[PW-1:0];
    localparam [PW-1:0] ONE    = ONE_W[PW-1:0];

    reg  [PW-1:0] ptr;
    reg  [PW-1:0] ptr_nxt;
    reg  [PW-1:0] winner;
    reg  [PW-1:0] idx;
    reg           found;
    integer       i;

    // Wrapping priority search. Every variable has a default first: no latch.
    always @* begin
        grant  = {N{1'b0}};
        winner = ptr;
        found  = 1'b0;
        idx    = ptr;
        for (i = 0; i < N; i = i + 1) begin
            if (!found && req[idx]) begin
                found  = 1'b1;
                winner = idx;
            end
            if (idx == LAST) idx = {PW{1'b0}};
            else             idx = idx + ONE;
        end
        if (found) grant[winner] = 1'b1;
        if (winner == LAST) ptr_nxt = {PW{1'b0}};
        else                ptr_nxt = winner + ONE;
    end

    // Pointer register: reset value and load enable only.
    always @(posedge clk) begin
        if (!rst_n)     ptr <= {PW{1'b0}};
        else if (found) ptr <= ptr_nxt;
    end

`ifdef FORMAL
    reg f_past_valid;
    initial f_past_valid = 1'b0;
    always @(posedge clk) f_past_valid <= 1'b1;

    // Reset is active on the first cycle.
    always @(*) if (!f_past_valid) assume (!rst_n);

    // Distance of the winner from the pointer, in round-robin order.
    wire [31:0] f_dw = (winner >= ptr) ? (winner - ptr) : (winner + N - ptr);

    always @(*) begin
        if (f_past_valid) begin
            assert (ptr <= LAST);
            assert ((grant & (grant - 1'b1)) == {N{1'b0}});
            assert ((grant & ~req) == {N{1'b0}});
            assert ((req == {N{1'b0}}) || (grant != {N{1'b0}}));
            assert (found == (grant != {N{1'b0}}));
            if (found)
                assert (grant[winner]);
        end
    end

    always @(posedge clk) begin
        if (f_past_valid) begin
            if (!$past(rst_n))
                assert (ptr == {PW{1'b0}});
            else if ($past(found))
                assert (ptr == (($past(winner) == LAST) ? {PW{1'b0}} : ($past(winner) + ONE)));
            else
                assert (ptr == $past(ptr));
        end
    end

    genvar fj;
    generate
        for (fj = 0; fj < N; fj = fj + 1) begin : g_fair
            localparam [31:0] FJ = fj;
            reg  [PW:0] f_wait;
            wire [31:0] f_dist = (FJ >= ptr) ? (FJ - ptr) : (FJ + N - ptr);

            // Cycles requester fj has waited with its request held.
            always @(posedge clk) begin
                if (!rst_n || !req[fj] || grant[fj])
                    f_wait <= {(PW+1){1'b0}};
                else
                    f_wait <= f_wait + 1'b1;
            end

            always @(*) begin
                if (f_past_valid) begin
                    assert (f_wait <= N - 1);
                    assert (f_wait + f_dist <= N - 1);
                    if (found && req[fj])
                        assert (f_dist >= f_dw);
                end
            end

            always @(*) begin
                cover (f_past_valid && rst_n && grant[fj]);
                cover (f_past_valid && rst_n && (f_wait == N - 1));
            end
        end
    endgenerate

    always @(*) begin
        cover (f_past_valid && rst_n && (req == {N{1'b1}}));
        cover (f_past_valid && rst_n && (req == {N{1'b0}}));
    end

    always @(posedge clk) begin
        if (f_past_valid)
            cover ($past(rst_n) && $past(found) && ($past(winner) == LAST) && (ptr == {PW{1'b0}}));
    end
`endif

endmodule

`ifdef FORMAL
// Formal-only wrapper: proves the arbiter at N 4 and at N 5 in one job.
module rr_arbiter_formal (
    input wire       clk,
    input wire       rst_n,
    input wire [3:0] req4,
    input wire [4:0] req5
);
    wire [3:0] grant4;
    wire [4:0] grant5;

    rr_arbiter #(.N(4)) u_n4 (.clk(clk), .rst_n(rst_n), .req(req4), .grant(grant4));
    rr_arbiter #(.N(5)) u_n5 (.clk(clk), .rst_n(rst_n), .req(req5), .grant(grant5));
endmodule
`endif

`default_nettype wire
=== END FILE ===
=== FILE: rr_arbiter_tb.v ===
// Self-checking testbench for rr_arbiter: N 4 and N 5 side by side.
/* verilator lint_off WIDTH */
/* verilator lint_off UNUSED */
/* verilator lint_off BLKSEQ */
/* verilator lint_off DECLFILENAME */
/* verilator lint_off MULTIDRIVEN */

// One arbiter plus its reference pointer model, fairness and coverage counters.
module rr_arbiter_chk #(
    parameter integer N = 4
) (
    input  wire         clk,
    input  wire         rst_n,
    input  wire [N-1:0] req,
    output wire [N-1:0] grant
);
    rr_arbiter #(.N(N)) dut (.clk(clk), .rst_n(rst_n), .req(req), .grant(grant));

    // Reference model: first requester at or after ref_ptr, modulo N.
    integer     ref_ptr;
    reg         ref_valid;
    reg [N-1:0] exp_grant;
    integer     exp_win;
    reg         exp_any;
    integer     k;
    integer     idx;

    always @* begin
        exp_grant = {N{1'b0}};
        exp_win   = 0;
        exp_any   = 1'b0;
        for (k = 0; k < N; k = k + 1) begin
            idx = (ref_ptr + k) % N;
            if (!exp_any && req[idx]) begin
                exp_any = 1'b1;
                exp_win = idx;
            end
        end
        if (exp_any) exp_grant[exp_win] = 1'b1;
    end

    integer     n_pass;
    integer     n_fail;
    integer     cov_none;
    integer     cov_all;
    integer     cov_held;
    integer     cov_longest;
    integer     cov_rst_traffic;
    reg [N-1:0] cov_alone;
    reg [N-1:0] cov_granted;
    reg [N-1:0] prev_req;
    reg         prev_rst_n;
    reg [N-1:0] one_j;
    integer     wait_cnt [0:N-1];
    integer     j;

    initial begin
        ref_ptr         = 0;
        ref_valid       = 1'b0;
        n_pass          = 0;
        n_fail          = 0;
        cov_none        = 0;
        cov_all         = 0;
        cov_held        = 0;
        cov_longest     = 0;
        cov_rst_traffic = 0;
        cov_alone       = {N{1'b0}};
        cov_granted     = {N{1'b0}};
        prev_req        = {N{1'b0}};
        prev_rst_n      = 1'b0;
        one_j           = {N{1'b0}};
        for (j = 0; j < N; j = j + 1) wait_cnt[j] = 0;
    end

    always @(posedge clk) begin
        if (ref_valid) begin
            // Grant against the reference model, every cycle.
            if (grant !== exp_grant) begin
                $error("rr_arbiter N=%0d: req=%b grant=%b expected=%b (reference pointer %0d)",
                       N, req, grant, exp_grant, ref_ptr);
                n_fail = n_fail + 1;
            end else begin
                n_pass = n_pass + 1;
            end

            if (rst_n) begin
                for (j = 0; j < N; j = j + 1) begin
                    // Fairness: a held request never waits N cycles.
                    if (req[j] && !grant[j]) begin
                        if (wait_cnt[j] >= N - 1) begin
                            $error("rr_arbiter N=%0d: requester %0d not granted after %0d waiting cycles",
                                   N, j, wait_cnt[j] + 1);
                            n_fail = n_fail + 1;
                        end else begin
                            n_pass = n_pass + 1;
                        end
                    end
                    if (grant[j]) cov_granted[j] = 1'b1;
                    if (grant[j] && (wait_cnt[j] == N - 1)) cov_longest = cov_longest + 1;
                    one_j    = {N{1'b0}};
                    one_j[j] = 1'b1;
                    if (req == one_j) cov_alone[j] = 1'b1;
                end
                if (req == {N{1'b0}}) cov_none = cov_none + 1;
                if (req == {N{1'b1}}) cov_all = cov_all + 1;
                if (prev_rst_n && ((req & prev_req) != {N{1'b0}}) && ((req ^ prev_req) != {N{1'b0}}))
                    cov_held = cov_held + 1;
            end else if (prev_rst_n && (req != {N{1'b0}})) begin
                cov_rst_traffic = cov_rst_traffic + 1;
            end

            for (j = 0; j < N; j = j + 1) begin
                if (!rst_n || !req[j] || grant[j]) wait_cnt[j] = 0;
                else                               wait_cnt[j] = wait_cnt[j] + 1;
            end
        end

        // Reference pointer update.
        if (!rst_n) begin
            ref_ptr   = 0;
            ref_valid = 1'b1;
        end else if (ref_valid && exp_any) begin
            ref_ptr = (exp_win + 1) % N;
        end
        prev_req   = req;
        prev_rst_n = rst_n;
    end
endmodule

module rr_arbiter_tb;
    reg        clk;
    reg        rst_n;
    reg  [3:0] req4;
    reg  [4:0] req5;
    wire [3:0] grant4;
    wire [4:0] grant5;

    integer        t_pass;
    integer        t_fail;
    integer        i;
    integer        passed;
    integer        failed;
    reg [31:0]     rnd;
    reg [8*64-1:0] nonce;

    initial begin
        clk    = 1'b0;
        rst_n  = 1'b0;
        req4   = 4'b0000;
        req5   = 5'b00000;
        t_pass = 0;
        t_fail = 0;
    end

    always #5 clk = ~clk;

    rr_arbiter_chk #(.N(4)) u4 (.clk(clk), .rst_n(rst_n), .req(req4), .grant(grant4));
    rr_arbiter_chk #(.N(5)) u5 (.clk(clk), .rst_n(rst_n), .req(req5), .grant(grant5));

    // Apply one cycle of stimulus at the falling edge.
    task cyc;
        input       r;
        input [3:0] r4;
        input [4:0] r5;
        begin
            @(negedge clk);
            rst_n = r;
            req4  = r4;
            req5  = r5;
        end
    endtask

    // Directed check of both grants, independent of the reference model.
    task chk_grant;
        input [3:0] e4;
        input [4:0] e5;
        begin
            #1;
            if (grant4 !== e4) begin
                $error("N=4 directed: req=%b grant=%b expected=%b", req4, grant4, e4);
                t_fail = t_fail + 1;
            end else begin
                t_pass = t_pass + 1;
            end
            if (grant5 !== e5) begin
                $error("N=5 directed: req=%b grant=%b expected=%b", req5, grant5, e5);
                t_fail = t_fail + 1;
            end else begin
                t_pass = t_pass + 1;
            end
        end
    endtask

    task goal;
        input            ok;
        input [8*40-1:0] what;
        begin
            if (ok) begin
                t_pass = t_pass + 1;
            end else begin
                $error("coverage goal not reached: %0s", what);
                t_fail = t_fail + 1;
            end
        end
    endtask

    initial begin
        // Phase 1: reset, without and then with traffic; pointer stays 0.
        cyc(1'b0, 4'b0000, 5'b00000);
        cyc(1'b0, 4'b0000, 5'b00000);
        cyc(1'b0, 4'b0110, 5'b01100); chk_grant(4'b0010, 5'b00100);
        cyc(1'b0, 4'b1000, 5'b10000); chk_grant(4'b1000, 5'b10000);

        // Phase 2: everyone requesting after reset: strict rotation from 0.
        for (i = 0; i < 20; i = i + 1) begin
            cyc(1'b1, 4'b1111, 5'b11111);
            chk_grant(4'b0001 << (i % 4), 5'b00001 << (i % 5));
        end

        // Phase 3: no requests.
        for (i = 0; i < 3; i = i + 1) begin
            cyc(1'b1, 4'b0000, 5'b00000);
            chk_grant(4'b0000, 5'b00000);
        end

        // Phase 4: each requester alone.
        for (i = 0; i < 5; i = i + 1) begin
            cyc(1'b1, (i < 4) ? (4'b0001 << i) : 4'b0000, 5'b00001 << i);
            chk_grant((i < 4) ? (4'b0001 << i) : 4'b0000, 5'b00001 << i);
        end

        // Phase 5: a held request among changing others.
        for (i = 0; i < 40; i = i + 1) begin
            rnd = $random;
            cyc(1'b1, rnd[3:0] | 4'b0010, rnd[8:4] | 5'b01000);
        end

        // Phase 6: longest fair wait. Grant the target alone, then everyone asks:
        // the target waits N-1 cycles and is granted on the N-th.
        cyc(1'b1, 4'b0100, 5'b01000); chk_grant(4'b0100, 5'b01000);
        for (i = 0; i < 5; i = i + 1) begin
            cyc(1'b1, 4'b1111, 5'b11111);
            chk_grant(4'b0001 << ((3 + i) % 4), 5'b00001 << ((4 + i) % 5));
        end

        // Phase 7: reset during traffic, then rotation restarts from 0.
        cyc(1'b1, 4'b1111, 5'b11111);
        cyc(1'b1, 4'b1111, 5'b11111);
        cyc(1'b0, 4'b1111, 5'b11111);
        cyc(1'b0, 4'b1010, 5'b10100); chk_grant(4'b0010, 5'b00100);
        for (i = 0; i < 6; i = i + 1) begin
            cyc(1'b1, 4'b1111, 5'b11111);
            chk_grant(4'b0001 << (i % 4), 5'b00001 << (i % 5));
        end

        // Phase 8: random traffic with occasional reset.
        for (i = 0; i < 600; i = i + 1) begin
            rnd = $random;
            cyc((rnd[31:27] != 5'b00000), rnd[3:0], rnd[8:4]);
        end

        cyc(1'b1, 4'b0000, 5'b00000);
        @(posedge clk);
        #1;

        // Coverage goals from the interface specification.
        goal(u4.cov_none > 0,          "N=4 no requests");
        goal(&u4.cov_alone,            "N=4 each requester alone");
        goal(u4.cov_all > 0,           "N=4 everyone requesting");
        goal(u4.cov_held > 0,          "N=4 held request, others changing");
        goal(u4.cov_longest > 0,       "N=4 longest fair wait");
        goal(u4.cov_rst_traffic > 0,   "N=4 reset during traffic");
        goal(&u4.cov_granted,          "N=4 every requester granted");
        goal(u5.cov_none > 0,          "N=5 no requests");
        goal(&u5.cov_alone,            "N=5 each requester alone");
        goal(u5.cov_all > 0,           "N=5 everyone requesting");
        goal(u5.cov_held > 0,          "N=5 held request, others changing");
        goal(u5.cov_longest > 0,       "N=5 longest fair wait");
        goal(u5.cov_rst_traffic > 0,   "N=5 reset during traffic");
        goal(&u5.cov_granted,          "N=5 every requester granted");

        if (!$value$plusargs("nirmaan_nonce=%s", nonce)) nonce = "unset";
        passed = t_pass + u4.n_pass + u5.n_pass;
        failed = t_fail + u4.n_fail + u5.n_fail;
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end
endmodule

/* verilator lint_on MULTIDRIVEN */
/* verilator lint_on DECLFILENAME */
/* verilator lint_on BLKSEQ */
/* verilator lint_on UNUSED */
/* verilator lint_on WIDTH */
=== END FILE ===
